{% extends "base_usuario.html" %}
{% block title %}Optimiza tu plan{% endblock %}
{% block head %}

(async function() {


  function computeCompleteness() {
    var required = [
      document.getElementById('field-edad').value,
      document.getElementById('field-peso').value,
      document.getElementById('field-estatura').value,
      document.getElementById('field-objetivo').value,
      document.getElementById('field-actividad').value,
    ];
    var optional = [
      document.getElementById('field-sexo').value,
      document.getElementById('field-grasa').value,
      document.getElementById('field-notas').value.trim(),
    ];
    var reqDone = required.filter(Boolean).length;
    var optDone = optional.filter(Boolean).length;
    return Math.round((reqDone / 5) * 80 + (optDone / 3) * 20);
  }

  function updateProgress() {
    var pct = computeCompleteness();
    var pctEl = document.getElementById('progress-pct');
    var fillEl = document.getElementById('progress-fill');
    var hintEl = document.getElementById('progress-hint');
    if (pctEl) pctEl.textContent = pct + '%';
    if (fillEl) fillEl.style.width = pct + '%';
    if (!hintEl) return;
    var missing = [
      document.getElementById('field-edad').value,
      document.getElementById('field-peso').value,
      document.getElementById('field-estatura').value,
      document.getElementById('field-objetivo').value,
      document.getElementById('field-actividad').value,
    ].filter(function(v) { return !v; }).length;
    if (pct === 0) {
      hintEl.textContent = 'Completa tus medidas para activar tu plan';
    } else if (missing > 0) {
      hintEl.textContent = 'Faltan ' + missing + ' dato' + (missing > 1 ? 's clave' : ' clave');
    } else if (pct < 100) {
      hintEl.textContent = 'Casi completo — datos opcionales mejoran la precisión';
    } else {
      hintEl.textContent = '¡Plan completamente optimizado!';
    }
  }

  var excluidos = [];
  var CAT_LABELS = {
    proteina: '🥩 Proteínas',
    carbs: '🍞 Carbohidratos',
    grasa: '🥑 Grasas',
    verdura: '🥦 Verduras',
    fruta: '🍎 Frutas'
  };

  function prettyName(s) {
    return s.replace(/_/g, ' ').replace(/\b\w/g, function(c) { return c.toUpperCase(); });
  }

  function renderTags() {
    var container = document.getElementById('excluidos-tags');
    if (!excluidos.length) {
      container.innerHTML = '<span class="u-excl-empty">No hay alimentos excluidos</span>';
      return;
    }
    // Stored profile data is text, including legacy records from before DTO validation.
    container.replaceChildren();
    excluidos.forEach(function(a) {
      var tag = document.createElement('span');
      tag.className = 'u-excl-tag';
      tag.append(document.createTextNode(prettyName(a)));
      var btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'u-excl-tag-remove';
      btn.dataset.food = a;
      btn.textContent = '×';
      btn.setAttribute('aria-label', 'Quitar exclusión de ' + prettyName(a));
      btn.addEventListener('click', function() {
        excluidos = excluidos.filter(function(x) { return x !== a; });
        renderTags();
        syncChips();
      });
      tag.append(btn);
      container.append(tag);
    });
  }

  function syncChips() {
    document.querySelectorAll('.u-excl-chip').forEach(function(chip) {
      var f = chip.getAttribute('data-food');
      chip.classList.toggle('u-excl-chip-active', excluidos.indexOf(f) !== -1);
    });
  }

  async function loadCatalogo() {
    try {
      var res = await fetch('/api/usuario/catalogo-alimentos', {
        headers: { 'Authorization': 'Bearer ' + localStorage.getItem('mb_token') }
      });
      if (!res.ok) throw new Error('Error cargando catálogo');
      var catalogo = await res.json();
      var container = document.getElementById('catalogo-container');
      var html = '';
      var order = ['proteina', 'carbs', 'grasa', 'verdura', 'fruta'];
      order.forEach(function(cat) {
        var items = catalogo[cat] || [];
        if (!items.length) return;
        html += '<div class="u-excl-group">';
        html += '<h4 class="u-excl-group-title">' + (CAT_LABELS[cat] || cat) + '</h4>';
        html += '<div class="u-excl-chips">';
        items.forEach(function(food) {
          var active = excluidos.indexOf(food) !== -1 ? ' u-excl-chip-active' : '';
          html += '<button type="button" class="u-excl-chip' + active + '" data-food="' + food + '">' + prettyName(food) + '</button>';
        });
        html += '</div></div>';
      });
      container.innerHTML = html;

      container.querySelectorAll('.u-excl-chip').forEach(function(chip) {
        chip.addEventListener('click', function() {
          var f = this.getAttribute('data-food');
          var idx = excluidos.indexOf(f);
          if (idx === -1) {
            excluidos.push(f);
          } else {
            excluidos.splice(idx, 1);
          }
          this.classList.toggle('u-excl-chip-active');
          renderTags();
        });
      });
    } catch(err) {
      document.getElementById('catalogo-container').innerHTML = '<p class="u-excl-error">No se pudo cargar el catálogo de alimentos.</p>';
    }
  }

  // Load current profile
  try {
    var res = await fetch('/api/usuario/perfil', {
      headers: { 'Authorization': 'Bearer ' + localStorage.getItem('mb_token') }
    });
    if (res.ok) {
      var p = await res.json();
      document.getElementById('field-nombre').value = p.nombre || '';
      document.getElementById('field-email').value = p.email || '';
      document.getElementById('field-edad').value = p.edad || '';
      document.getElementById('field-peso').value = p.peso_kg || '';
      document.getElementById('field-estatura').value = p.estatura_cm || '';
      document.getElementById('field-sexo').value = p.sexo || '';
      document.getElementById('field-grasa').value = p.grasa_corporal_pct || '';
      document.getElementById('field-objetivo').value = p.objetivo || '';
      document.getElementById('field-actividad').value = p.nivel_actividad || '';
      document.getElementById('field-notas').value = p.notas || '';
      excluidos = Array.isArray(p.alimentos_excluidos) ? p.alimentos_excluidos : [];
      renderTags();
      updateProgress();
    }
  } catch(err) {}

  await loadCatalogo();

  // Live progress on any field change
  ['field-edad', 'field-peso', 'field-estatura', 'field-sexo', 'field-grasa',
   'field-objetivo', 'field-actividad', 'field-notas'].forEach(function(id) {
    var el = document.getElementById(id);
    if (el) el.addEventListener('input', updateProgress);
  });

  // Save profile
  document.getElementById('form-perfil').addEventListener('submit', async function(e) {
    e.preventDefault();
    var btn = document.getElementById('btn-guardar');
    btn.disabled = true;
    btn.textContent = 'Actualizando...';

    var payload = {
      edad: parseInt(document.getElementById('field-edad').value) || null,
      peso_kg: parseFloat(document.getElementById('field-peso').value) || null,
      estatura_cm: parseFloat(document.getElementById('field-estatura').value) || null,
      sexo: document.getElementById('field-sexo').value || null,
      grasa_corporal_pct: parseFloat(document.getElementById('field-grasa').value) || null,
      objetivo: document.getElementById('field-objetivo').value || null,
      nivel_actividad: document.getElementById('field-actividad').value || null,
      notas: document.getElementById('field-notas').value || null,
      alimentos_excluidos: excluidos,
    };

    try {
      var res = await fetch('/api/usuario/perfil', {
        method: 'PUT',
        headers: {
          'Authorization': 'Bearer ' + localStorage.getItem('mb_token'),
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(payload),
      });
      if (!res.ok) {
        var err = await res.json().catch(function() { return {}; });
        throw new Error(err.detail || 'Error guardando perfil');
      }
      var isComplete = computeCompleteness() >= 80;
      showToast(isComplete
        ? '✅ Plan actualizado · Ve a Mi Plan para regenerarlo'
        : '✅ Datos guardados · Completa tu perfil para un plan más preciso');
    } catch(e) {
      showToast('❌ ' + e.message, 'error');
    } finally {
      btn.disabled = false;
      btn.innerHTML = '<svg width="16" height="16" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"><path stroke-linecap="round" stroke-linejoin="round" d="M5 13l4 4L19 7"/></svg> Actualizar mi plan';
    }
  });

  function showToast(msg, type) {
    var c = document.getElementById('toast-container');
    if (!c) return;
    var t = document.createElement('div');
    t.className = 'u-toast' + (type === 'error' ? ' u-toast-error' : '');
    t.textContent = msg;
    c.appendChild(t);
    setTimeout(function() { t.remove(); }, 4000);
  }

})();
